final_template:
AWSTemplateFormatVersion: "2010-09-09"

Description: >
  Creates an AWS IoT Core policy for device onboarding. The policy allows
  devices to connect, publish, subscribe, and receive on their own
  thing-name-scoped topics. A Lambda-backed custom resource (Node.js 24.x)
  manages the policy lifecycle.

Parameters:
  PolicyName:
    Type: String
    Default: DeviceOnboardingPolicy
    Description: Name of the IoT Core policy created for device onboarding.

  TopicPrefix:
    Type: String
    Default: "${iot:Connection.Thing.ThingName}"
    Description: >
      MQTT topic prefix scoping each device to its own thing name. Uses the
      IoT Core policy template variable so the policy is resolved at runtime
      to the connecting device's thing name.

Resources:
  # IAM role for Lambda function execution
  PolicyLambdaRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: "2012-10-17"
        Statement:
          - Effect: Allow
            Principal:
              Service: lambda.amazonaws.com
            Action: sts:AssumeRole
      ManagedPolicyArns:
        - arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole
      Policies:
        - PolicyName: IoTDeviceOnboardingPolicyAccess
          PolicyDocument:
            Version: "2012-10-17"
            Statement:
              - Effect: Allow
                Action:
                  - iot:CreatePolicy
                  - iot:DeletePolicy
                  - iot:GetPolicy
                Resource:
                  - "*"

  # Lambda function that backs the custom resource
  PolicyLambda:
    Type: AWS::Lambda::Function
    Properties:
      Handler: index.handler
      Role: !GetAtt PolicyLambdaRole.Arn
      Runtime: nodejs24.x
      Timeout: 60
      MemorySize: 128
      Code:
        ZipFile: |
          'use strict';

          const https = require('https');

          let iot;

          try {
            const AWS = require('aws-sdk');
            const client = new AWS.IoT({ maxRetries: 3 });
            iot = {
              createPolicy: (params) => client.createPolicy(params).promise(),
              deletePolicy: (params) => client.deletePolicy(params).promise()
            };
          } catch (err) {
            const { IoTClient, CreatePolicyCommand, DeletePolicyCommand } = require('@aws-sdk/client-iot');
            const client = new IoTClient({ maxAttempts: 3, region: process.env.AWS_REGION });
            iot = {
              createPolicy: (params) => client.send(new CreatePolicyCommand(params)),
              deletePolicy: (params) => client.send(new DeletePolicyCommand(params))
            };
          }

          function sendResponse(responseUrl, body) {
            return new Promise((resolve, reject) => {
              const p = new URL(responseUrl);
              const data = JSON.stringify(body);
              const req = https.request({
                hostname: p.hostname,
                port: 443,
                path: p.pathname + p.search,
                method: 'PUT',
                headers: { 'Content-Type': '', 'Content-Length': Buffer.byteLength(data) }
              }, (res) => resolve());
              req.on('error', reject);
              req.write(data);
              req.end();
            });
          }

          function policyDoc(prefix) {
            const t = prefix || '${iot:Connection.Thing.ThingName}';
            return {
              Version: '2012-10-17',
              Statement: [
                { Effect: 'Allow', Action: ['iot:Connect'], Resource: ['*'] },
                {
                  Effect: 'Allow',
                  Action: ['iot:Publish', 'iot:Receive'],
                  Resource: [`arn:aws:iot:*:*:topic/${t}/*`]
                },
                {
                  Effect: 'Allow',
                  Action: ['iot:Subscribe'],
                  Resource: [`arn:aws:iot:*:*:topicfilter/${t}/*`]
                }
              ]
            };
          }

          exports.handler = async (event) => {
            const props = event.ResourceProperties || {};
            const type = event.RequestType;
            let status = 'SUCCESS';
            let reason = '';
            let id = event.PhysicalResourceId || event.LogicalResourceId;
            let data = {};

            try {
              if (type === 'Create') {
                const name = props.PolicyName || 'DeviceOnboardingPolicy';
                await iot.createPolicy({
                  policyName: name,
                  policyDocument: JSON.stringify(policyDoc(props.TopicPrefix))
                });
                id = name;
                data = { PolicyName: name };
                console.log(`Created IoT policy ${name}`);
              } else if (type === 'Update') {
                if (event.PhysicalResourceId) {
                  try {
                    await iot.deletePolicy({ policyName: event.PhysicalResourceId });
                  } catch (e) {
                    console.log(`Could not delete old policy: ${e.message}`);
                  }
                }
                const name = props.PolicyName || 'DeviceOnboardingPolicy';
                await iot.createPolicy({
                  policyName: name,
                  policyDocument: JSON.stringify(policyDoc(props.TopicPrefix))
                });
                id = name;
                data = { PolicyName: name };
                console.log(`Updated IoT policy ${name}`);
              } else if (type === 'Delete' && event.PhysicalResourceId) {
                try {
                  await iot.deletePolicy({ policyName: event.PhysicalResourceId });
                  console.log(`Deleted IoT policy ${event.PhysicalResourceId}`);
                } catch (e) {
                  console.log(`Could not delete policy: ${e.message}`);
                }
              }
            } catch (e) {
              status = 'FAILED';
              reason = e.message;
              console.error(e);
            }

            await sendResponse(event.ResponseURL, {
              Status: status,
              Reason: reason,
              PhysicalResourceId: id,
              StackId: event.StackId,
              RequestId: event.RequestId,
              LogicalResourceId: event.LogicalResourceId,
              Data: data
            });
          };
      Environment:
        Variables:
          AWS_NODEJS_CONNECTION_REUSE_ENABLED: "1"

  # Custom resource that provisions the IoT Core policy via the Lambda
  DeviceOnboardingPolicy:
    Type: Custom::IoTCorePolicy
    Properties:
      ServiceToken: !GetAtt PolicyLambda.Arn
      PolicyName: !Ref PolicyName
      TopicPrefix: !Ref TopicPrefix

Outputs:
  DevicePolicyName:
    Description: Name of the generated IoT Core policy.
    Value: !GetAtt DeviceOnboardingPolicy.PolicyName

AWSTemplateFormatVersion: "2010-09-09"
Description: >-
  Amazon Verified Permissions policy store with a strict Bookstore Cedar schema,
  static Cedar policies, and an SSM parameter that publishes the policy store ID.

Resources:
  BookstorePolicyStore:
    Type: AWS::VerifiedPermissions::PolicyStore
    Properties:
      Description: Bookstore Cedar policy store with strict schema validation.
      ValidationSettings:
        Mode: STRICT
      Schema:
        CedarJson: |
          {
            "Bookstore": {
              "entityTypes": {
                "Role": {},
                "User": {
                  "memberOfTypes": ["Role"],
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "yearsAsMember": {
                        "type": "Long",
                        "required": false
                      }
                    }
                  }
                },
                "Book": {
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "owner": {
                        "type": "Entity",
                        "name": "Bookstore::User",
                        "required": true
                      }
                    }
                  }
                }
              },
              "actions": {
                "View": {
                  "appliesTo": {
                    "principalTypes": ["User"],
                    "resourceTypes": ["Book"],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "type": "String",
                          "required": true
                        }
                      }
                    }
                  }
                },
                "ViewWithPremiumOffers": {
                  "appliesTo": {
                    "principalTypes": ["User"],
                    "resourceTypes": ["Book"],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "type": "String",
                          "required": true
                        }
                      }
                    }
                  }
                }
              }
            }
          }

  AdminViewPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Administrators may view every book.
          Statement: |
            permit(
              principal in Bookstore::Role::"Admin",
              action == Bookstore::Action::"View",
              resource
            );

  ForbidSpecificAdminViewPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Explicitly deny the named administrator from viewing books.
          Statement: |
            forbid(
              principal == Bookstore::User::"AdminUser",
              action == Bookstore::Action::"View",
              resource
            );

  PublisherViewOwnedBooksPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Publishers may view only the books that they own.
          Statement: |
            permit(
              principal in Bookstore::Role::"Publisher",
              action == Bookstore::Action::"View",
              resource
            )
            when {
              resource.owner == principal
            };

  SpecificUserViewSpecificBookPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Allow the named user to view the named book.
          Statement: |
            permit(
              principal == Bookstore::User::"BookReader",
              action == Bookstore::Action::"View",
              resource == Bookstore::Book::"TheGreatBook"
            );

  CustomerPremiumOffersPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Customers may view premium offers after two or more years of membership.
          Statement: |
            permit(
              principal in Bookstore::Role::"Customer",
              action == Bookstore::Action::"ViewWithPremiumOffers",
              resource
            )
            when {
              principal has yearsAsMember &&
              principal.yearsAsMember >= 2
            };

  ForbidNewCustomerPremiumOffersPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Explicitly deny customers with less than two years of membership from viewing premium offers.
          Statement: |
            forbid(
              principal in Bookstore::Role::"Customer",
              action == Bookstore::Action::"ViewWithPremiumOffers",
              resource
            )
            when {
              principal has yearsAsMember &&
              principal.yearsAsMember < 2
            };

  ForbidNonUsRegionPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Explicitly deny both view actions when the request region is not the United States.
          Statement: |
            forbid(
              principal,
              action in [
                Bookstore::Action::"View",
                Bookstore::Action::"ViewWithPremiumOffers"
              ],
              resource
            )
            when {
              context.region != "US"
            };

  PolicyStoreIdParameter:
    Type: AWS::SSM::Parameter
    Properties:
      Name: /bookstore/verified-permissions/policy-store-id
      Description: Amazon Verified Permissions policy store ID for the Bookstore application.
      Type: String
      Value: !Ref BookstorePolicyStore
